//! Version capabilities and ecosystem classifications for DJI `.txt` flight logs.
//!
//! DJI flight telemetry logs evolved across 14 major versions (v1 through v14),
//! altering header layout, record length encoding, encryption/scrambling methods,
//! and metadata block positions.

use std::fmt;

use crate::error::FlightReaderError;

/// Ground station application ecosystem identifying originating software.
///
/// Extracted from byte offset 11 (`0x0B`) in the fixed header.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Department {
    /// Pre-production, unknown, or legacy testbed software (0).
    Unknown,
    /// DJI Mobile SDK custom enterprise applications (1).
    Sdk,
    /// DJI GO / DJI GO 4 mobile applications (2).
    DjiGo,
    /// DJI Fly consumer mobile application (3).
    DjiFly,
    /// DJI Agras / MG agricultural machinery app (4).
    AgriculturalMachinery,
    /// DJI Terra photogrammetry mapping workstation (5).
    Terra,
    /// DJI Pilot / DJI Pilot 2 enterprise ground station (7).
    DjiPilot,
    /// Ground Station Pro surveying application for iPadOS (8).
    GsPro,
    /// Fallback for unmapped or future department codes.
    Custom(u8),
}

#[allow(non_upper_case_globals)]
impl Department {
    /// Constant alias for `Department::Sdk`.
    pub const SDK: Self = Self::Sdk;
    /// Constant alias for `Department::DjiGo`.
    pub const DJIGO: Self = Self::DjiGo;
    /// Constant alias for `Department::DjiFly`.
    pub const DJIFly: Self = Self::DjiFly;
    /// Constant alias for `Department::DjiPilot`.
    pub const DJIPilot: Self = Self::DjiPilot;
    /// Constant alias for `Department::GsPro`.
    pub const GSPro: Self = Self::GsPro;

    /// Convert a raw byte into a [`Department`].
    #[must_use]
    pub const fn from_u8(val: u8) -> Self {
        match val {
            0 => Self::Unknown,
            1 => Self::Sdk,
            2 => Self::DjiGo,
            3 => Self::DjiFly,
            4 => Self::AgriculturalMachinery,
            5 => Self::Terra,
            7 => Self::DjiPilot,
            8 => Self::GsPro,
            other => Self::Custom(other),
        }
    }

    /// Convert this [`Department`] back into its raw byte representation.
    #[must_use]
    pub const fn as_u8(&self) -> u8 {
        match *self {
            Self::Unknown => 0,
            Self::Sdk => 1,
            Self::DjiGo => 2,
            Self::DjiFly => 3,
            Self::AgriculturalMachinery => 4,
            Self::Terra => 5,
            Self::DjiPilot => 7,
            Self::GsPro => 8,
            Self::Custom(val) => val,
        }
    }
}

impl From<u8> for Department {
    fn from(val: u8) -> Self {
        Self::from_u8(val)
    }
}

impl From<Department> for u8 {
    fn from(dept: Department) -> Self {
        dept.as_u8()
    }
}

impl fmt::Display for Department {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unknown => write!(f, "Unknown"),
            Self::Sdk => write!(f, "DJI SDK"),
            Self::DjiGo => write!(f, "DJI GO"),
            Self::DjiFly => write!(f, "DJI Fly"),
            Self::AgriculturalMachinery => write!(f, "Agricultural Machinery"),
            Self::Terra => write!(f, "DJI Terra"),
            Self::DjiPilot => write!(f, "DJI Pilot"),
            Self::GsPro => write!(f, "GS Pro"),
            Self::Custom(val) => write!(f, "Custom({val})"),
        }
    }
}

/// Cryptographic protection mechanism employed on record payloads.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ScrambleType {
    /// Plaintext unencrypted record payloads (v1–v6).
    None,
    /// Cyclic XOR keystream derived via ECMA-182 CRC64 (v7–v12).
    Xor,
    /// AES-256-CBC cipher with dynamic IV chaining and keychain (v13–v14).
    Aes,
}

impl fmt::Display for ScrambleType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::None => write!(f, "None"),
            Self::Xor => write!(f, "XOR (CRC64)"),
            Self::Aes => write!(f, "AES-256-CBC"),
        }
    }
}

/// Physical location of the summary / details block relative to the file.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DetailsLocation {
    /// Summary details block is located at EOF, pointed to by `details_offset` (v1–v11).
    EndOfFile,
    /// Details block is located at fixed offset 100/101; telemetry records begin at `details_offset` (v12–v14).
    HeaderOffset,
}

impl fmt::Display for DetailsLocation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::EndOfFile => write!(f, "End of File"),
            Self::HeaderOffset => write!(f, "Header Offset"),
        }
    }
}

/// Structural and cryptographic capabilities defined by a DJI `.txt` log version.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct VersionCapabilities {
    /// Major log version (1 through 14).
    pub version: u8,
    /// Width of the record payload length field in bytes (1 for v1..=6, 2 for v7..=14).
    pub record_len_width: usize,
    /// Payload encryption / scrambling method.
    pub scramble_type: ScrambleType,
    /// Location of the details summary partition.
    pub details_location: DetailsLocation,
}

impl VersionCapabilities {
    /// Classify the given log version into its architectural capabilities.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::UnsupportedVersion`] if `version` is not in `1..=14`.
    pub fn classify(version: u8) -> Result<Self, FlightReaderError> {
        classify_version(version)
    }
}

/// Alias for [`VersionCapabilities`] for compatibility with specification conventions.
pub type TxtVersion = VersionCapabilities;

/// Classify a DJI `.txt` log version into its architectural and cryptographic capabilities.
///
/// # Invariants
/// - Versions 1 through 6: 1-byte length width, no scrambling, details at EOF.
/// - Versions 7 through 11: 2-byte length width, cyclic XOR scrambling, details at EOF.
/// - Version 12: 2-byte length width, cyclic XOR scrambling, details relocated to header offset.
/// - Versions 13 through 14: 2-byte length width, AES encryption, details at header offset.
/// - All other versions: rejected with [`FlightReaderError::UnsupportedVersion`].
///
/// # Errors
/// Returns [`FlightReaderError::UnsupportedVersion`] if `version` is not in `1..=14`.
pub fn classify_version(version: u8) -> Result<VersionCapabilities, FlightReaderError> {
    match version {
        1..=6 => Ok(VersionCapabilities {
            version,
            record_len_width: 1,
            scramble_type: ScrambleType::None,
            details_location: DetailsLocation::EndOfFile,
        }),
        7..=11 => Ok(VersionCapabilities {
            version,
            record_len_width: 2,
            scramble_type: ScrambleType::Xor,
            details_location: DetailsLocation::EndOfFile,
        }),
        12 => Ok(VersionCapabilities {
            version,
            record_len_width: 2,
            scramble_type: ScrambleType::Xor,
            details_location: DetailsLocation::HeaderOffset,
        }),
        13..=14 => Ok(VersionCapabilities {
            version,
            record_len_width: 2,
            scramble_type: ScrambleType::Aes,
            details_location: DetailsLocation::HeaderOffset,
        }),
        unsupported => Err(FlightReaderError::UnsupportedVersion {
            version: unsupported,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_classify_v1_to_v6() {
        for v in 1..=6 {
            let caps = classify_version(v).expect("v1..=6 must be supported");
            assert_eq!(caps.version, v);
            assert_eq!(caps.record_len_width, 1);
            assert_eq!(caps.scramble_type, ScrambleType::None);
            assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
        }
    }

    #[test]
    fn test_classify_v7_to_v11() {
        for v in 7..=11 {
            let caps = classify_version(v).expect("v7..=11 must be supported");
            assert_eq!(caps.version, v);
            assert_eq!(caps.record_len_width, 2);
            assert_eq!(caps.scramble_type, ScrambleType::Xor);
            assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
        }
    }

    #[test]
    fn test_classify_v12() {
        let caps = classify_version(12).expect("v12 must be supported");
        assert_eq!(caps.version, 12);
        assert_eq!(caps.record_len_width, 2);
        assert_eq!(caps.scramble_type, ScrambleType::Xor);
        assert_eq!(caps.details_location, DetailsLocation::HeaderOffset);
    }

    #[test]
    fn test_classify_v13_and_v14() {
        for v in [13, 14] {
            let caps = classify_version(v).expect("v13..=14 must be supported");
            assert_eq!(caps.version, v);
            assert_eq!(caps.record_len_width, 2);
            assert_eq!(caps.scramble_type, ScrambleType::Aes);
            assert_eq!(caps.details_location, DetailsLocation::HeaderOffset);
        }
    }

    #[test]
    fn test_classify_unsupported_versions() {
        for invalid_v in [0, 15, 16, 42, 100, 255] {
            let err = classify_version(invalid_v).unwrap_err();
            assert_eq!(
                err,
                FlightReaderError::UnsupportedVersion { version: invalid_v }
            );
        }
    }

    #[test]
    fn test_version_capabilities_method_alias() {
        let caps = VersionCapabilities::classify(8).unwrap();
        assert_eq!(caps.version, 8);
        assert_eq!(caps.record_len_width, 2);

        let err = TxtVersion::classify(0).unwrap_err();
        assert_eq!(err, FlightReaderError::UnsupportedVersion { version: 0 });
    }

    #[test]
    fn test_department_from_and_to_u8() {
        assert_eq!(Department::from_u8(0), Department::Unknown);
        assert_eq!(Department::from_u8(1), Department::Sdk);
        assert_eq!(Department::from_u8(2), Department::DjiGo);
        assert_eq!(Department::from_u8(3), Department::DjiFly);
        assert_eq!(Department::from_u8(4), Department::AgriculturalMachinery);
        assert_eq!(Department::from_u8(5), Department::Terra);
        assert_eq!(Department::from_u8(7), Department::DjiPilot);
        assert_eq!(Department::from_u8(8), Department::GsPro);
        assert_eq!(Department::from_u8(6), Department::Custom(6));
        assert_eq!(Department::from_u8(9), Department::Custom(9));
        assert_eq!(Department::from_u8(255), Department::Custom(255));

        // Test roundtrip for all 256 bytes
        for b in 0..=255u8 {
            let dept = Department::from(b);
            let back: u8 = dept.into();
            assert_eq!(b, back);
        }
    }

    #[test]
    fn test_department_constant_aliases() {
        assert_eq!(Department::SDK, Department::Sdk);
        assert_eq!(Department::DJIGO, Department::DjiGo);
        assert_eq!(Department::DJIFly, Department::DjiFly);
        assert_eq!(Department::DJIPilot, Department::DjiPilot);
        assert_eq!(Department::GSPro, Department::GsPro);
    }

    #[test]
    fn test_display_implementations() {
        assert_eq!(Department::Unknown.to_string(), "Unknown");
        assert_eq!(Department::Sdk.to_string(), "DJI SDK");
        assert_eq!(Department::DjiFly.to_string(), "DJI Fly");
        assert_eq!(Department::Custom(99).to_string(), "Custom(99)");

        assert_eq!(ScrambleType::None.to_string(), "None");
        assert_eq!(ScrambleType::Xor.to_string(), "XOR (CRC64)");
        assert_eq!(ScrambleType::Aes.to_string(), "AES-256-CBC");

        assert_eq!(DetailsLocation::EndOfFile.to_string(), "End of File");
        assert_eq!(DetailsLocation::HeaderOffset.to_string(), "Header Offset");
    }
}

//! DJI `.txt` flight log binary header parser.
//!
//! Parses the initial 100-byte or 101-byte fixed binary header containing stream offsets,
//! format versions, application ecosystem flags, and cryptographic markers.

use byteorder::{ByteOrder, LittleEndian};

use super::version::{classify_version, Department, VersionCapabilities};
use crate::error::FlightReaderError;

/// Parsed fixed binary header from a DJI `.txt` mobile flight record.
///
/// Every DJI flight telemetry log commences with either a 100-byte or 101-byte
/// header defining stream boundaries and metadata.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TxtHeader {
    /// Byte offset where the details summary block (v1–v11) or telemetry records (v12–v14) reside.
    pub details_offset: i64,
    /// Declared header length in bytes (`100` or `101`).
    pub header_length: i16,
    /// Format major version number (`1` through `14`).
    pub version: u8,
    /// DJI ground station application ecosystem identifier.
    pub department: Department,
    /// Cryptographic status byte (`0` = plaintext, `!= 0` = scrambled / encrypted).
    pub scrambled_flag: u8,
    /// Reserved compatibility bytes (offsets 13 through 99, 87 bytes total).
    pub reserved: [u8; 87],
    /// Header padding byte present strictly when `header_length == 101` (offset 100).
    pub padding: Option<u8>,
}

impl TxtHeader {
    /// Minimum byte size required to inspect a standard DJI `.txt` header.
    pub const MIN_HEADER_SIZE: usize = 100;
    /// Extended byte size for modern headers containing an extra padding byte.
    pub const EXTENDED_HEADER_SIZE: usize = 101;

    /// Parse a fixed binary header from the provided byte slice with zero allocations.
    ///
    /// # Protocol Specification
    /// - Bytes 0..8: `details_offset` (`i64`, Little-Endian)
    /// - Bytes 8..10: `header_length` (`i16`, Little-Endian, must be 100 or 101)
    /// - Byte 10: `version` (`u8`, must be in `1..=14`)
    /// - Byte 11: `department` (`u8` mapped to [`Department`])
    /// - Byte 12: `scrambled_flag` (`u8`)
    /// - Bytes 13..100: `reserved` (`[u8; 87]`)
    /// - Byte 100: `padding` (`Option<u8>`, present only if `header_length == 101`)
    ///
    /// # Errors
    /// - [`FlightReaderError::UnexpectedEof`] if `input.len() < 100`, or `input.len() < 101` when `header_length == 101`.
    /// - [`FlightReaderError::InvalidHeaderLength`] if `header_length` is not 100 or 101.
    /// - [`FlightReaderError::UnsupportedVersion`] if `version` is not supported (1..=14).
    /// - [`FlightReaderError::CorruptedHeader`] if `details_offset < 0`.
    pub fn parse(input: &[u8]) -> Result<Self, FlightReaderError> {
        if input.len() < Self::MIN_HEADER_SIZE {
            return Err(FlightReaderError::UnexpectedEof);
        }

        let details_offset = LittleEndian::read_i64(&input[0..8]);
        if details_offset < 0 {
            return Err(FlightReaderError::CorruptedHeader);
        }

        let header_length = LittleEndian::read_i16(&input[8..10]);
        if header_length != 100 && header_length != 101 {
            return Err(FlightReaderError::InvalidHeaderLength {
                length: header_length,
            });
        }

        let padding = if header_length == 101 {
            if input.len() < Self::EXTENDED_HEADER_SIZE {
                return Err(FlightReaderError::UnexpectedEof);
            }
            Some(input[100])
        } else {
            None
        };

        let version = input[10];
        // Validate version against capability matrix (rejects versions not in 1..=14)
        classify_version(version)?;

        let department = Department::from_u8(input[11]);
        let scrambled_flag = input[12];

        let mut reserved = [0u8; 87];
        reserved.copy_from_slice(&input[13..100]);

        Ok(Self {
            details_offset,
            header_length,
            version,
            department,
            scrambled_flag,
            reserved,
            padding,
        })
    }

    /// Check whether the flight log records are scrambled or encrypted.
    #[must_use]
    pub const fn is_scrambled(&self) -> bool {
        self.scrambled_flag != 0
    }

    /// Obtain architectural capabilities for this log's format version.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::UnsupportedVersion`] if the version is unhandled.
    pub fn capabilities(&self) -> Result<VersionCapabilities, FlightReaderError> {
        classify_version(self.version)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::txt::version::{DetailsLocation, ScrambleType};

    /// Helper to assemble a synthetic header byte buffer.
    fn make_synthetic_header(
        details_offset: i64,
        header_len: i16,
        version: u8,
        dept: u8,
        scrambled: u8,
        padding_byte: Option<u8>,
    ) -> Vec<u8> {
        let total_len = if let Some(_) = padding_byte { 101 } else { 100 };
        let mut buf = vec![0u8; total_len];
        LittleEndian::write_i64(&mut buf[0..8], details_offset);
        LittleEndian::write_i16(&mut buf[8..10], header_len);
        buf[10] = version;
        buf[11] = dept;
        buf[12] = scrambled;
        if let Some(pad) = padding_byte {
            buf[100] = pad;
        }
        buf
    }

    #[test]
    fn test_synthetic_headers_v1_to_v14() {
        // Test definitions matching test_vectors.md Section 3.2
        let test_cases = [
            (1u8, 100i16, 2u8, 0u8, 10000i64, None),
            (2, 100, 2, 0, 12000, None),
            (3, 100, 2, 0, 15000, None),
            (4, 100, 2, 0, 18000, None),
            (5, 100, 2, 0, 20000, None),
            (6, 100, 2, 0, 25000, None),
            (7, 100, 2, 1, 50000, None),
            (8, 100, 3, 1, 60000, None),
            (9, 100, 3, 1, 70000, None),
            (10, 100, 3, 1, 80000, None),
            (11, 100, 7, 1, 90000, None),
            (12, 100, 3, 1, 100, None),
            (13, 100, 3, 1, 100, None),
            (13, 101, 3, 1, 101, Some(0u8)),
            (14, 100, 3, 1, 100, None),
            (14, 101, 7, 1, 101, Some(0u8)),
        ];

        for (ver, hlen, dept, scram, off, pad) in test_cases {
            let bytes = make_synthetic_header(off, hlen, ver, dept, scram, pad);
            let parsed = TxtHeader::parse(&bytes).expect("Valid header must parse cleanly");

            assert_eq!(parsed.version, ver);
            assert_eq!(parsed.header_length, hlen);
            assert_eq!(parsed.department, Department::from_u8(dept));
            assert_eq!(parsed.scrambled_flag, scram);
            assert_eq!(parsed.details_offset, off);
            assert_eq!(parsed.padding, pad);
            assert_eq!(parsed.is_scrambled(), scram != 0);

            // Capabilities match version
            let caps = parsed.capabilities().expect("Valid capabilities");
            assert_eq!(caps.version, ver);
            if ver <= 6 {
                assert_eq!(caps.scramble_type, ScrambleType::None);
                assert_eq!(caps.record_len_width, 1);
                assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
            } else if ver <= 11 {
                assert_eq!(caps.scramble_type, ScrambleType::Xor);
                assert_eq!(caps.record_len_width, 2);
                assert_eq!(caps.details_location, DetailsLocation::EndOfFile);
            } else if ver == 12 {
                assert_eq!(caps.scramble_type, ScrambleType::Xor);
                assert_eq!(caps.record_len_width, 2);
                assert_eq!(caps.details_location, DetailsLocation::HeaderOffset);
            } else {
                assert_eq!(caps.scramble_type, ScrambleType::Aes);
                assert_eq!(caps.record_len_width, 2);
                assert_eq!(caps.details_location, DetailsLocation::HeaderOffset);
            }
        }
    }

    #[test]
    fn test_error_truncated_inputs() {
        // Empty slice
        assert_eq!(
            TxtHeader::parse(&[]).unwrap_err(),
            FlightReaderError::UnexpectedEof
        );

        // 8 bytes (only details_offset)
        let eight_bytes = vec![0u8; 8];
        assert_eq!(
            TxtHeader::parse(&eight_bytes).unwrap_err(),
            FlightReaderError::UnexpectedEof
        );

        // 13 bytes (partial header)
        let thirteen_bytes = vec![0u8; 13];
        assert_eq!(
            TxtHeader::parse(&thirteen_bytes).unwrap_err(),
            FlightReaderError::UnexpectedEof
        );

        // 99 bytes (1 byte short)
        let ninety_nine = vec![0u8; 99];
        assert_eq!(
            TxtHeader::parse(&ninety_nine).unwrap_err(),
            FlightReaderError::UnexpectedEof
        );

        // Header claims 101 bytes, but buffer has only 100 bytes
        let mut h101_short = make_synthetic_header(100, 101, 13, 3, 1, None);
        assert_eq!(h101_short.len(), 100);
        assert_eq!(
            TxtHeader::parse(&h101_short).unwrap_err(),
            FlightReaderError::UnexpectedEof
        );
    }

    #[test]
    fn test_error_invalid_header_lengths() {
        // header_length = 0
        let h_zero = make_synthetic_header(100, 0, 1, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_zero).unwrap_err(),
            FlightReaderError::InvalidHeaderLength { length: 0 }
        );

        // header_length = 99
        let h_99 = make_synthetic_header(100, 99, 1, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_99).unwrap_err(),
            FlightReaderError::InvalidHeaderLength { length: 99 }
        );

        // header_length = 102
        let h_102 = make_synthetic_header(100, 102, 1, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_102).unwrap_err(),
            FlightReaderError::InvalidHeaderLength { length: 102 }
        );

        // header_length = -1
        let h_neg = make_synthetic_header(100, -1, 1, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_neg).unwrap_err(),
            FlightReaderError::InvalidHeaderLength { length: -1 }
        );
    }

    #[test]
    fn test_error_unsupported_versions() {
        // version = 0
        let h_v0 = make_synthetic_header(100, 100, 0, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_v0).unwrap_err(),
            FlightReaderError::UnsupportedVersion { version: 0 }
        );

        // version = 15
        let h_v15 = make_synthetic_header(100, 100, 15, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_v15).unwrap_err(),
            FlightReaderError::UnsupportedVersion { version: 15 }
        );

        // version = 255
        let h_v255 = make_synthetic_header(100, 100, 255, 2, 0, None);
        assert_eq!(
            TxtHeader::parse(&h_v255).unwrap_err(),
            FlightReaderError::UnsupportedVersion { version: 255 }
        );
    }

    #[test]
    fn test_error_negative_details_offset() {
        let h_neg_off = make_synthetic_header(-1, 100, 1, 2, 0, None);
        assert_eq!(
